    1 -> if (dark) Color(0xFFF6D653) else Color(0xFFBD8100)
    2 -> if (dark) Color(0xFFFBC83E) else Color(0xFFC27800)
    3 -> if (dark) Color(0xFFFFB928) else Color(0xFFC66E00)
    4 -> if (dark) Color(0xFFFFAA13) else Color(0xFFCA6400)
    5 -> if (dark) Color(0xFFFF9B03) else Color(0xFFCD5900)
    6 -> if (dark) Color(0xFFFF8B0A) else Color(0xFFD04E00)
    7 -> if (dark) Color(0xFFFF7C1D) else Color(0xFFD24100)
    8 -> if (dark) Color(0xFFFF6C2D) else Color(0xFFD33300)
    9 -> if (dark) Color(0xFFFE5B3D) else Color(0xFFD32107)
